### ✅ C++コード（300行以内）

```cpp
#include <iostream>
#include <fstream>
#include <thread>
#include <vector>
#include <mutex>
#include <filesystem>
#include <sstream>
#include <map>
#include <chrono>
#include <ctime>
#include <string>
#include <cmath>
#include <iomanip>
#include <boost/property_tree/ptree.hpp>
#include <boost/property_tree/json_parser.hpp>

using namespace std;
using namespace std::chrono;

mutex mtx;
int processed_files = 0;
int total_files = 0;

void load_data(const string& file_path, map<string, string>& data) {
    try {
        if (file_path.ends_with(".csv")) {
            ifstream file(file_path);
            string line;
            while (getline(file, line)) {
                istringstream iss(line);
                string key, value;
                getline(iss, key, ',');
                getline(iss, value);
                data[key] = value;
            }
        } else if (file_path.ends_with(".json")) {
            boost::property_tree::ptree pt;
            ifstream json_file(file_path);
            read_json(json_file, pt);
            for (const auto& p : pt) {
                data[p.first] = p.second.data();
            }
        }
    } catch (...) {
        cout << "Error reading file: " << file_path << endl;
    }
}

void analyze_support_chats(const map<string, string>& data, map<string, double>& result) {
    // 仮想の分析処理
    result["avg_response_time"] = 0.0;
    result["satisfaction_distribution"] = 0.0;
    result["frequent_queries"] = 0;
}

void analyze_sales(const map<string, string>& data, map<string, double>& result) {
    // 仮想の分析処理
    result["daily_sales"] = 0.0;
    result["purchase_frequency"] = 0.0;
    result["popular_products"] = 0;
}

void generate_report(const map<string, double>& data, const string& type) {
    // 仮想のレポート生成
    cout << "Generating " << type << " report..." << endl;
}

void save_to_db(const map<string, double>& data, const string& db_type) {
    // 仮想のデータベース保存
    cout << "Saving to " << db_type << " database..." << endl;
}

void process_file(const string& file_path) {
    map<string, string> data;
    load_data(file_path, data);
    if (!data.empty()) {
        map<string, double> support_result, sales_result;
        analyze_support_chats(data, support_result);
        analyze_sales(data, sales_result);
        save_to_db(support_result, "support");
        save_to_db(sales_result, "sales");
        generate_report(support_result, "csv");
        generate_report(sales_result, "pdf");
    }
    {
        lock_guard<mutex> lock(mtx);
        processed_files++;
        double progress = (static_cast<double>(processed_files) / total_files) * 100;
        cout << "\rProcessing: " << processed_files << "/" << total_files << " (" << fixed << setprecision(2) << progress << "%)" << flush;
    }
}

int main() {
    try {
        filesystem::path data_dir("/path/to/data");
        vector<string> files;
        for (const auto& entry : filesystem::directory_iterator(data_dir)) {
            if (entry.is_regular_file()) {
                files.push_back(entry.path().string());
            }
        }
        total_files = files.size();
        if (total_files == 0) {
            cout << "No files found in the directory." << endl;
            return 1;
        }

        thread_pool pool(4);
        for (const auto& file : files) {
            pool.enqueue(process_file, file);
        }
        pool.wait();
    } catch (const exception& e) {
        cerr << "Error: " << e.what() << endl;
        return 1;
    }
    return 0;
}
```

