### ✅ C++ Code (Under 300 Lines)

```cpp
#include <iostream>
#include <fstream>
#include <thread>
#include <vector>
#include <mutex>
#include <string>
#include <sstream>
#include <unordered_map>
#include <chrono>
#include <filesystem>
#include <nlohmann/json.hpp>
#include <csvpp/csv.hpp>
#include <fmt/core.h>

namespace fs = std::filesystem;
using json = nlohmann::json;

std::mutex mtx;
std::vector<std::string> results;

void process_file(const std::string& file_path, const std::string& type) {
    std::ifstream file(file_path);
    if (!file.is_open()) {
        fmt::print("Error opening file: {}\n", file_path);
        return;
    }

    std::vector<std::string> lines;
    std::string line;
    while (std::getline(file, line)) {
        lines.push_back(line);
    }

    std::unordered_map<std::string, std::string> data;
    for (const auto& l : lines) {
        std::istringstream iss(l);
        std::string key, value;
        if (std::getline(iss, key, ',') && std::getline(iss, value)) {
            data[key] = value;
        }
    }

    // Simple deduplication (for demo)
    std::vector<std::string> unique_data;
    std::unordered_set<std::string> seen;
    for (const auto& [k, v] : data) {
        std::string key = k + "," + v;
        if (seen.find(key) == seen.end()) {
            seen.insert(key);
            unique_data.push_back(key);
        }
    }

    std::lock_guard<std::mutex> lock(mtx);
    results.insert(results.end(), unique_data.begin(), unique_data.end());
}

void process_files() {
    std::vector<std::thread> threads;
    for (const auto& entry : fs::directory_iterator("/path/to/data")) {
        if (entry.path().extension() == ".json") {
            threads.emplace_back(process_file, entry.path().string(), "chat");
        } else if (entry.path().extension() == ".csv") {
            threads.emplace_back(process_file, entry.path().string(), "transaction");
        }
    }

    for (auto& t : threads) {
        t.join();
    }
}

int main() {
    fmt::print("Starting data processing pipeline...\n");
    auto start = std::chrono::steady_clock::now();
    process_files();
    auto end = std::chrono::steady_clock::now();
    fmt::print("Processing completed in {} seconds\n", std::chrono::duration_cast<std::chrono::seconds>(end - start).count());
    return 0;
}
```

