### ✅ C++ Code with Detailed Comments

```cpp
#include <iostream>
#include <fstream>
#include <thread>
#include <vector>
#include <mutex>
#include <string>
#include <sstream>
#include <unordered_map>
#include <chrono>
#include <filesystem>
#include <nlohmann/json.hpp>
#include <csvpp/csv.hpp>
#include <fmt/core.h>

namespace fs = std::filesystem;
using json = nlohmann::json;

std::mutex mtx;  // Mutex for thread-safe access to shared data
std::vector<std::string> results;  // Store results from all threads

/**
 * @brief Processes a single file (CSV or JSON) based on its type.
 * 
 * This function reads the file line by line, extracts key-value pairs,
 * performs basic deduplication, and stores the result in a shared vector.
 * 
 * @param file_path Path to the file being processed.
 * @param type Type of the file (e.g., "chat", "transaction").
 */
void process_file(const std::string& file_path, const std::string& type) {
    std::ifstream file(file_path);  // Open the file for reading
    if (!file.is_open()) {
        fmt::print("Error opening file: {}\n", file_path);  // Log error if file can't be opened
        return;
    }

    std::vector<std::string> lines;  // Store all lines of the file
    std::string line;
    while (std::getline(file, line)) {
        lines.push_back(line);  // Read each line into the vector
    }

    std::unordered_map<std::string, std::string> data;  // Store key-value pairs from the file
    for (const auto& l : lines) {
        std::istringstream iss(l);  // Create a string stream for the line
        std::string key, value;
        if (std::getline(iss, key, ',') && std::getline(iss, value)) {
            data[key] = value;  // Extract key and value and store in map
        }
    }

    // Simple deduplication: check for unique combinations of key-value pairs
    std::vector<std::string> unique_data;
    std::unordered_set<std::string> seen;
    for (const auto& [k, v] : data) {
        std::string key = k + "," + v;  // Combine key and value to form a unique identifier
        if (seen.find(key) == seen.end()) {
            seen.insert(key);  // Add to seen set to avoid duplicates
            unique_data.push_back(key);  // Add unique entry to results
        }
    }

    // Use a lock to safely add results to the shared vector
    std::lock_guard<std::mutex> lock(mtx);
    results.insert(results.end(), unique_data.begin(), unique_data.end());
}

/**
 * @brief Processes all files in the specified directory.
 * 
 * This function iterates over all files in the directory, starts a new thread
 * for each file, and waits for all threads to complete.
 * 
 * It supports both CSV and JSON file types, and processes them accordingly.
 */
void process_files() {
    std::vector<std::thread> threads;  // Vector to hold all threads
    for (const auto& entry : fs::directory_iterator("/path/to/data")) {
        // Check if the file is a JSON or CSV file
        if (entry.path().extension() == ".json") {
            threads.emplace_back(process_file, entry.path().string(), "chat");  // Process chat JSON files
        } else if (entry.path().extension() == ".csv") {
            threads.emplace_back(process_file, entry.path().string(), "transaction");  // Process transaction CSV files
        }
    }

    // Wait for all threads to complete
    for (auto& t : threads) {
        t.join();
    }
}

/**
 * @brief Main function that starts the data processing pipeline.
 * 
 * It logs the start time, runs the file processing, and logs the total processing time.
 */
int main() {
    fmt::print("Starting data processing pipeline...\n");  // Log the start of the pipeline
    auto start = std::chrono::steady_clock::now();  // Record the start time

    process_files();  // Call the function to process all files

    auto end = std::chrono::steady_clock::now();  // Record the end time
    fmt::print("Processing completed in {} seconds\n", 
               std::chrono::duration_cast<std::chrono::seconds>(end - start).count());  // Log the total processing time
    return 0;
}
```

